478	// Transfer 由当前持有人发起转让。接收人必须已登记、可用且不同于当前
479	// 持有人；请求必须给出期望持有人与期望版本，藏品不存在或持有人/版本
480	// 不符时返回业务拒绝且不改变任何状态。成交价款（分）由持有人填写，
481	// 非负、未填按 0；成功时按所属系列的版税规则一次落盘各收款账户的
482	// 应付明细与归转让前持有人的余款。同一 (操作者, 请求号) 的相同
483	// 请求重复提交（即使藏品后来已易手）返回首次结果。
484	//
485	// 状态类拒绝的落盘失败时，与整批转让一致：返回保存错误（保留实际写入
486	// 错误）而非该业务错误，结果为空（无藏品编号、无持有变化、无历史序号、
487	// 无金额、业务错误为空、不标回放），请求号不被这次未保存的拒绝占用；
488	// 保存条件恢复后用完全相同的请求重提，按当时的业务状态重新判断：拒绝
489	// 条件仍在则重新保存此次拒绝并返回对应业务错误，状态已变为满足请求则
490	// 正常转出。
491	//
492	// 成功转让同样以保存完成为准：持有换人、版本加一、转让历史、版税应付、
493	// 历史序号与请求结果都尚未写入原登记册而保存失败（如数据位置暂时无法
494	// 写入）时，返回实际保存错误而非转让成功，结果为空（不携带藏品编号、前后
495	// 持有人、版本、历史序号、价款、应付或余款，业务错误为空，不标回放）。
496	// 即使失败后原数据暂时无法读取、状态未能按磁盘重建，这笔转让也必须从当前
497	// 仍打开的登记册中整体撤销：藏品仍属于提交前的持有人、版本不增加、持有
498	// 列表与藏品历史保持原状、版税查询没有本次计算记录、收款账户不多出应付，
499	// 请求号与历史序号都不被消耗；失败前已存在的成功转让、应付与其他藏品记录
500	// 原样保留，随后另一次无关操作成功保存也不会把这笔未保存的转让一并写入。
501	// 读写条件恢复后用原操作者、请求号、原因和全部转让参数重新提交，按当时的
502	// 持有与账户状态重新判断：条件仍满足时正常完成一次转让（版本只增加一次、
503	// 序号紧接已有历史、不标回放），此后再次提交相同内容才回放这一笔已保存的
504	// 结果；恢复期间藏品已被另一笔合法转让转出的，原请求按现有版本冲突规则
505	// 拒绝，不能回放先前未保存的成功。
506	func (r *Registry) Transfer(req TransferRequest) (TransferResult, error) {
507		if err := req.validatePresent(); err != nil {
508			return TransferResult{}, err
509		}
510		r.mu.Lock()
511		defer r.mu.Unlock()
512		if err := r.checkOpen(); err != nil {
513			return TransferResult{}, err
514		}
515	
516		key := requestKey(req.Operator, req.RequestID)
517		sig := transferParamsSig(req)
518		if prev, ok := r.state.Requests[key]; ok {
519			return r.replayTransfer(prev, sig)
520		}
521	
522		bizErr := r.checkTransfer(req)
523		if bizErr != nil {
524			if !isValidationErr(bizErr) {
525				// 状态类业务拒绝（持有人/版本不符、账户停用、收发同人等）
526				// 占用请求号并落盘，相同参数重提永远返回这一次拒绝。
527				r.state.Requests[key] = request{
528					Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
529					Params: sig, Rejected: true, Reason: errCode(bizErr),
530					ItemID: req.ItemID,
531				}
532				if err := r.commit(); err != nil {
533					// 拒绝结果落盘失败：这次拒绝没有被记住，与整批转让一致——
534					// 不能只用业务错误掩盖保存错误，调用者稍后用原请求重提时
535					// 必须按当时状态重新判断，而不是回放一个实际没有保存的
536					// 拒绝。commit 失败时已按磁盘内容重建状态，请求记录随之
537					// 撤销；此处再删一次以覆盖磁盘暂时不可读、状态未能重建
538					// 的情形。整体返回空结果：无藏品编号、无持有变化、无历史
539					// 序号、无金额、不标回放、结果中业务错误为空，error 保留
540					// 实际写入错误。
541					delete(r.state.Requests, key)
542					return TransferResult{}, err
543				}
544			}
545			// 藏品或账户不存在等校验错误不占用请求号，也不改变持有或历史。
546			return TransferResult{ItemID: req.ItemID, Err: bizErr}, bizErr
547		}
548	
549		// 回滚基点：本次成功转让的全部改动（持有换人、版本加一、历史、版税
550		// 应付、历史序号、请求结果）都必须以一次保存完成为准。记录改动前的
551		// 持有、历史长度与历史序号，保存失败且磁盘暂时不可读、状态未能按磁盘
552		// 重建时据此整体撤销，否则后续任何一次成功保存都会把这笔未保存的转让
553		// 带进登记册，造成"已换人、可回放"的幻影交易。
554		prevHolding := r.state.Holdings[req.ItemID]
555		prevNextSeq := r.state.NextSeq
556		prevHistLen := len(r.state.History)
557	
558		// 持有变化、历史、版税应付与请求结果在同一临界区内一次落盘。
559		out := r.applyTransfer(req.ItemID, req.ToID, req.Operator, req.Reason, req.RequestID, "", req.Price)
560		r.state.Requests[key] = request{
561			Operator: req.Operator, RequestID: req.RequestID, Kind: "transfer",
562			Params: sig, ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
563			Version: out.toVer(), TxSeq: out.seq,
564		}
565		if err := r.commit(); err != nil {
566			// commit 失败时已尝试按磁盘内容重建状态：重建成功则本次改动已随
567			// 旧状态整体撤销（持有未换人、无本次历史与应付、请求记录不存在、
568			// 序号未消耗），无需再动；磁盘暂时不可读、状态未能重建时本次改动
569			// 仍在，据此把这笔未保存的转让全部撤销，让当前已打开的登记册回到
570			// 提交前状态，也不被随后另一次成功保存带入。返回空结果：无藏品
571			// 编号、无前后持有人、无版本、无历史序号、无价款/应付/余款、不标
572			// 回放、结果中业务错误为空，error 保留实际写入错误。
573			if _, pending := r.state.Requests[key]; pending {
574				delete(r.state.Requests, key)
575				delete(r.state.Royalties, out.seq)
576				r.state.History = r.state.History[:prevHistLen]
577				r.state.Holdings[req.ItemID] = prevHolding
578				r.state.NextSeq = prevNextSeq
579			}
580			return TransferResult{}, err
581		}
582		return TransferResult{ItemID: req.ItemID, FromID: out.fromID, ToID: req.ToID,
583			Version: out.toVer(), TxSeq: out.seq,
584			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
585			Remainder: out.royalty.Remainder}, nil
586	}
587	
588	// checkTransfer 按单件转让的优先级执行与整批共用的直接转让资格规则：
589	// 参数合法后，藏品及持有记录不存在优先于账户错误，操作者的登记和停用
590	// 问题优先于接收账户问题，接收账户问题优先于收发同人，收发同人又优先
591	// 于持有信息不符。
592	func (r *Registry) checkTransfer(req TransferRequest) error {
593		return r.checkSingleTransferEligibility(directTransferEligibility{
594			itemID:        req.ItemID,
595			operator:      req.Operator,
596			toID:          req.ToID,
597			expectedOwner: req.ExpectedOwner,
598			expectedVer:   req.ExpectedVer,
599		})
600	}
