602	func (r *Registry) replayTransfer(prev request, sig string) (TransferResult, error) {
603		if prev.Kind != "transfer" || prev.Params != sig {
604			return TransferResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
605				ErrRequestConflict, prev.Operator, prev.RequestID)
606		}
607		res := TransferResult{ItemID: prev.ItemID, FromID: prev.FromID, ToID: prev.ToID,
608			Version: prev.Version, TxSeq: prev.TxSeq, Replayed: true}
609		if prev.Rejected {
610			res.Err = codeErr(prev.Reason)
611			return res, res.Err
612		}
613		// 回放首次成功的金额：即使藏品后来再次易手或进程重开，仍返回原
614		// 价款与应付明细，不重复计入。
615		res.Price, res.Payables, res.Remainder = r.royaltyOfTx(prev.TxSeq)
616		return res, nil
617	}
