636	func (req CreateAuthorizationRequest) validatePresent() error {
637		missing := []string{}
638		if strings.TrimSpace(req.Operator) == "" {
639			missing = append(missing, "operator")
640		}
641		if strings.TrimSpace(req.Reason) == "" {
642			missing = append(missing, "reason")
643		}
644		if strings.TrimSpace(req.RequestID) == "" {
645			missing = append(missing, "request_id")
646		}
647		if strings.TrimSpace(req.AuthID) == "" {
648			missing = append(missing, "auth_id")
649		}
650		if strings.TrimSpace(req.ItemID) == "" {
651			missing = append(missing, "item_id")
652		}
653		if strings.TrimSpace(req.TrusteeID) == "" {
654			missing = append(missing, "trustee_id")
655		}
656		if strings.TrimSpace(req.ToID) == "" {
657			missing = append(missing, "to_id")
658		}
659		if strings.TrimSpace(req.ExpectedOwner) == "" {
660			missing = append(missing, "expected_owner")
661		}
662		if req.ExpectedVer <= 0 {
663			missing = append(missing, "expected_version")
664		}
665		if req.ExpiresAt.IsZero() {
666			missing = append(missing, "expires_at")
667		}
668		if len(missing) > 0 {
669			return fmt.Errorf("%w: 创建授权请求缺少必填字段 %s", ErrInvalidArgument, strings.Join(missing, ", "))
670		}
671		if req.Price < 0 {
672			return fmt.Errorf("%w: 成交价款 %d 不能为负", ErrInvalidArgument, req.Price)
673		}
674		return nil
675	}
