848	func (r *Registry) replayCreateAuthz(prev request, sig string) (CreateAuthorizationResult, error) {
849		if prev.Kind != "auth_create" || prev.Params != sig {
850			return CreateAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
851				ErrRequestConflict, prev.Operator, prev.RequestID)
852		}
853		res := CreateAuthorizationResult{AuthID: prev.AuthID, GrantVer: prev.Version,
854			Status: AuthActive, Replayed: true}
855		if prev.Rejected {
856			res.Err = codeErr(prev.Reason)
857			return res, res.Err
858		}
859		return res, nil
860	}
