979	// recordRevokeRejection 登记撤销授权的状态类业务拒绝（非授权人的
980	// ErrForbidden、授权人撤销已使用授权的 ErrAuthorizationUsed）并落盘。
981	// 拒绝结果以保存完成为准：落盘失败时显式撤销尚未保存的请求号占用并返回
982	// 实际保存错误，调用方必须返回空结果与该错误，不能只返回业务拒绝让调用者
983	// 误以为拒绝已经记住；落盘成功时返回 nil，由调用方返回业务拒绝本身。
984	func (r *Registry) recordRevokeRejection(key, sig string, req RevokeAuthorizationRequest, bizErr error) error {
985		r.state.Requests[key] = request{
986			Operator: req.Operator, RequestID: req.RequestID, Kind: "auth_revoke",
987			Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
988		}
989		if err := r.commit(); err != nil {
990			// commit 失败时已尝试按磁盘内容重建状态，请求记录随之撤销；此处再
991			// 删一次以覆盖磁盘暂时不可读、状态未能重建的情形——未保存的拒绝
992			// 不能留在当前已打开的登记册中，也不能随随后另一次正常操作被保存。
993			delete(r.state.Requests, key)
994			return err
995		}
996		return nil
997	}
