999	func (r *Registry) replayRevokeAuthz(prev request, sig string) (RevokeAuthorizationResult, error) {
1000		if prev.Kind != "auth_revoke" || prev.Params != sig {
1001			return RevokeAuthorizationResult{}, fmt.Errorf("%w: 操作者 %s 的请求号 %s 已用于不同请求",
1002				ErrRequestConflict, prev.Operator, prev.RequestID)
1003		}
1004		res := RevokeAuthorizationResult{AuthID: prev.AuthID, Status: AuthRevoked, Replayed: true}
1005		if prev.Rejected {
1006			res.Err = codeErr(prev.Reason)
1007			res.Status = ""
1008			return res, res.Err
1009		}
1010		return res, nil
1011	}
