1013	func proxyTransferParamsSig(req ProxyTransferRequest) string {
1014		b, _ := json.Marshal(struct {
1015			Kind   string `json:"kind"`
1016			AuthID string `json:"auth_id"`
1017			Reason string `json:"reason"`
1018		}{"proxy_transfer", req.AuthID, req.Reason})
1019		return string(b)
1020	}
