1022	// ProxyTransfer 由受托人凭授权发起一次性代转。藏品与接收人均以授权
1023	// 记载为准，请求本身不能指定。成功后持有人变为授权中的接收人、持有
1024	// 版本加一，授权记为已使用并关联该笔转让；代转同样出现在藏品历史中，
1025	// 操作者记为实际受托账户并可通过授权编号追溯。
1026	//
1027	// 非受托人（ErrForbidden）、授权已撤销（ErrAuthorizationRevoked）、
1028	// 已到期（ErrAuthorizationExpired）、已使用（ErrAuthorizationUsed）、
1029	// 任一相关账户停用（ErrAccountInactive）以及持有版本已变化
1030	// （ErrConflict，即使藏品回到授权人手中也不恢复）分别明确拒绝，拒绝
1031	// 不改变持有或授权状态。成功代转用原请求号重放时，即使授权已到期、
1032	// 账户已停用或藏品再次易手，仍返回首次的转让结果。
1033	//
1034	// 上述状态类拒绝以保存完成为准：拒绝结果尚未写入原登记册而保存失败（如
1035	// 数据位置暂时无法写入）时，返回实际保存错误，不能只返回到期、无权或停用
1036	// 等业务拒绝让调用者误以为这次拒绝已经记住；结果为空（不带授权或藏品编号、
1037	// 不带转让和金额信息、不标回放，结果内的业务错误也为空），error 保留实际
1038	// 写入失败原因。这次未保存的拒绝不改变授权内容、使用标记、授权变更记录，
1039	// 也不改变藏品持有人、版本、转让历史与版税应付，并不占用操作者的本次请求
1040	// 号——即使保存失败后原数据暂时无法读取、状态未能按磁盘重建，未保存的拒绝
1041	// 也不能留在当前已打开的登记册中，或随随后另一次成功保存被记住。保存条件
1042	// 恢复后用完全相同的请求重提，按重提时的业务状态重新判断，而不是回放失败
1043	// 时的拒绝（例如到期拒绝保存失败、授权随后被撤销时，重提返回已撤销）；这次
1044	// 重新处理若保存成功不标回放，此后原样重提才回放已保存的结果。已经成功保存
1045	// 的拒绝仍按首次结果回放，改动该请求的业务内容仍报请求号冲突；必填内容缺失
1046	// 或引用不存在沿用原错误且不占用请求号。
1047	func (r *Registry) ProxyTransfer(req ProxyTransferRequest) (ProxyTransferResult, error) {
1048		missing := []string{}
1049		if strings.TrimSpace(req.Operator) == "" {
1050			missing = append(missing, "operator")
1051		}
1052		if strings.TrimSpace(req.Reason) == "" {
1053			missing = append(missing, "reason")
1054		}
1055		if strings.TrimSpace(req.RequestID) == "" {
1056			missing = append(missing, "request_id")
1057		}
1058		if strings.TrimSpace(req.AuthID) == "" {
1059			missing = append(missing, "auth_id")
1060		}
1061		if len(missing) > 0 {
1062			return ProxyTransferResult{}, fmt.Errorf("%w: 代转请求缺少必填字段 %s",
1063				ErrInvalidArgument, strings.Join(missing, ", "))
1064		}
1065		r.mu.Lock()
1066		defer r.mu.Unlock()
1067		if err := r.checkOpen(); err != nil {
1068			return ProxyTransferResult{}, err
1069		}
1070	
1071		now := r.now()
1072		key := requestKey(req.Operator, req.RequestID)
1073		sig := proxyTransferParamsSig(req)
1074		if prev, ok := r.state.Requests[key]; ok {
1075			return r.replayProxyTransfer(prev, sig)
1076		}
1077	
1078		if bizErr := r.checkProxyTransfer(req, now); bizErr != nil {
1079			if !isValidationErr(bizErr) {
1080				// 状态类业务拒绝（无权、已撤销、已到期、已使用、停用、版本已
1081				// 变化）占用请求号并落盘：相同参数重提返回这一次拒绝。
1082				r.state.Requests[key] = request{
1083					Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1084					Params: sig, Rejected: true, Reason: errCode(bizErr), AuthID: req.AuthID,
1085				}
1086				if err := r.commit(); err != nil {
1087					// 拒绝结果落盘失败：这次拒绝没有被记住，与发行、转让、授权
1088					// 创建/撤销一致——不能用业务错误掩盖保存错误，调用者稍后用
1089					// 原请求重提时必须按当时状态重新判断，而不是回放一个实际没有
1090					// 保存的拒绝。此分支在写入前只动了请求记录，没有改变持有、
1091					// 授权或版税；commit 失败时已按磁盘内容重建状态，请求记录随之
1092					// 撤销，此处再删一次以覆盖磁盘暂时不可读、状态未能重建的情形。
1093					// 整体返回空结果：不带授权或藏品编号、不带转让和金额信息、不标
1094					// 回放、结果中业务错误为空，error 保留实际写入错误。
1095					delete(r.state.Requests, key)
1096					return ProxyTransferResult{}, err
1097				}
1098			}
1099			// 必填缺失、授权或账户不存在等校验错误不占用请求号，也不改变持有、
1100			// 授权状态或授权变更记录。
1101			return ProxyTransferResult{AuthID: req.AuthID, Err: bizErr}, bizErr
1102		}
1103	
1104		a := r.state.Authzs[req.AuthID]
1105		// 代转价款以授权创建时记载为准，执行时不得改价；余款归转让前持有
1106		// 人（授权人），不记给受托人。持有变化、历史、应付明细与授权使用
1107		// 状态在同一临界区内一次落盘；历史记录实际受托账户并可按授权编号
1108		// 追溯。
1109		out := r.applyTransfer(a.ItemID, a.ToID, req.Operator, req.Reason, req.RequestID, a.ID, a.Price)
1110		a.Status = "used"
1111		a.UsedTxSeq = out.seq
1112		a.UsedAt = now
1113		r.state.Authzs[a.ID] = a
1114		authSeq := r.state.NextAuthSeq + 1
1115		r.state.NextAuthSeq = authSeq
1116		r.state.AuthEvents = append(r.state.AuthEvents, authzEvent{
1117			Seq: authSeq, AuthID: a.ID, ItemID: a.ItemID, Kind: "use",
1118			Operator: req.Operator, Reason: req.Reason, RequestID: req.RequestID,
1119			FromStatus: AuthActive, ToStatus: AuthUsed, TxSeq: out.seq, OccurredAt: now,
1120		})
1121		r.state.Requests[key] = request{
1122			Operator: req.Operator, RequestID: req.RequestID, Kind: "proxy_transfer",
1123			Params: sig, AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID, ToID: a.ToID,
1124			Version: out.toVer(), TxSeq: out.seq,
1125		}
1126		if err := r.commit(); err != nil {
1127			return ProxyTransferResult{}, err
1128		}
1129		return ProxyTransferResult{AuthID: a.ID, ItemID: a.ItemID, FromID: out.fromID,
1130			ToID: a.ToID, Version: out.toVer(), TxSeq: out.seq,
1131			Price: out.royalty.Price, Payables: publicPayables(out.royalty.Payees),
1132			Remainder: out.royalty.Remainder}, nil
1133	}
